import java.util.*;

public class BoxingDemo {
    public static void main(String[] args) {
        // Autoboxing: primitive int -> Integer object
        Integer count = 42;  // compiler: Integer.valueOf(42)

        // Unboxing: Integer object -> primitive int
        int value = count;   // compiler: count.intValue()

        // Collections require wrapper types
        List<Integer> numbers = new ArrayList<>();
        numbers.add(10);     // autoboxing happens here
        numbers.add(20);

        int sum = 0;
        for (Integer num : numbers) {
            sum += num;      // unboxing happens here
        }

        // HashMap with wrapper types
        Map<String, Integer> scores = new HashMap<>();
        scores.put("Alice", 95);  // autoboxing
        int aliceScore = scores.get("Alice");  // unboxing
    }
}

import java.util.*;

public class UnboxingNPE {
    public static void main(String[] args) {
        Map<String, Integer> userScores = new HashMap<>();
        userScores.put("Alice", 95);
        userScores.put("Bob", 87);

        // DANGER: throws NPE if key doesn't exist
        int charlieScore = userScores.get("Charlie");  // get() returns null
        // Compiler turns this into: userScores.get("Charlie").intValue()
        // Calling .intValue() on null throws NPE

        // SAFE: use getOrDefault to avoid null
        int safeScore = userScores.getOrDefault("Charlie", 0);

        // SAFE: check for null before unboxing
        Integer rawScore = userScores.get("Diana");
        int dianaScore = (rawScore != null) ? rawScore : 0;

        // SAFE: use wrapper type to allow null
        Integer maybeNull = userScores.get("Eve");  // no unboxing, stays null
        if (maybeNull != null) {
            System.out.println(maybeNull);
        }
    }
}

import java.util.*;
import java.util.stream.*;

public class BoxingPerformance {
    public static void main(String[] args) {
        int size = 10_000_000;

        // SLOW: boxing on every iteration
        List<Integer> boxedList = new ArrayList<>();
        long start = System.currentTimeMillis();
        for (int i = 0; i < size; i++) {
            boxedList.add(i);  // autoboxing creates Integer object
        }
        int sum = 0;
        for (Integer num : boxedList) {
            sum += num;  // unboxing on every addition
        }
        System.out.println("Boxed: " + (System.currentTimeMillis() - start) + "ms");

        // FAST: pure primitives, no boxing
        int[] primitiveArray = new int[size];
        start = System.currentTimeMillis();
        for (int i = 0; i < size; i++) {
            primitiveArray[i] = i;  // direct memory write
        }
        int sum2 = 0;
        for (int num : primitiveArray) {
            sum2 += num;  // no unboxing overhead
        }
        System.out.println("Primitive: " + (System.currentTimeMillis() - start) + "ms");

        // FAST: specialized primitive stream avoids boxing
        long sum3 = IntStream.range(0, size).sum();
    }
}

public class IntegerCacheDemo {
    public static void main(String[] args) {
        // Small integers: cached, == works
        Integer a = 100;
        Integer b = 100;
        System.out.println(a == b);        // true (same cached object)
        System.out.println(a.equals(b));   // true

        // Large integers: not cached, == fails
        Integer x = 200;
        Integer y = 200;
        System.out.println(x == y);        // false (different objects)
        System.out.println(x.equals(y));   // true (correct way)

        // Explicit new always creates separate object
        Integer c = new Integer(100);  // deprecated but illustrates point
        Integer d = 100;
        System.out.println(c == d);        // false (new bypasses cache)

        // Autoboxing uses cache
        Integer cached = Integer.valueOf(50);  // cache hit
        Integer alsoCached = 50;               // autoboxing calls valueOf
        System.out.println(cached == alsoCached);  // true

        // The safe way for all comparisons
        System.out.println(x.equals(y));   // always use this
    }
}
